import os
from typing import Dict, Any, List, Optional
import boto3
from botocore.exceptions import ClientError

class DocumentExtractor:
    def __init__(self):
        self.client = boto3.client(
            'textract',
            region_name=os.getenv('AWS_REGION', 'us-east-1'),
            aws_access_key_id=os.getenv('AWS_ACCESS_KEY_ID'),
            aws_secret_access_key=os.getenv('AWS_SECRET_ACCESS_KEY')
        )

    def extract_and_validate(self, document_bytes: bytes, required_fields: List[str]) -> Dict[str, Any]:
        try:
            response = self.client.analyze_document(
                Document={'Bytes': document_bytes},
                FeatureTypes=['FORMS']
            )

            extracted_fields = {}
            confidence_scores = {}

            for block in response.get('Blocks', []):
                if block['BlockType'] == 'KEY_VALUE_SET':
                    if 'KEY' in block.get('EntityTypes', []):
                        key_text = ''
                        value_text = ''
                        key_confidence = 0
                        value_confidence = 0

                        for relationship in block.get('Relationships', []):
                            if relationship['Type'] == 'CHILD':
                                for child_id in relationship['Ids']:
                                    child_block = next(
                                        (b for b in response['Blocks'] if b['Id'] == child_id),
                                        None
                                    )
                                    if child_block and child_block['BlockType'] == 'WORD':
                                        key_text += child_block['Text'] + ' '
                                        key_confidence = child_block.get('Confidence', 0)

                        for relationship in block.get('Relationships', []):
                            if relationship['Type'] == 'VALUE':
                                for value_id in relationship['Ids']:
                                    value_block = next(
                                        (b for b in response['Blocks'] if b['Id'] == value_id),
                                        None
                                    )
                                    if value_block and value_block['BlockType'] == 'KEY_VALUE_SET':
                                        for rel in value_block.get('Relationships', []):
                                            if rel['Type'] == 'CHILD':
                                                for child_id in rel['Ids']:
                                                    child_block = next(
                                                        (b for b in response['Blocks'] if b['Id'] == child_id),
                                                        None
                                                    )
                                                    if child_block and child_block['BlockType'] == 'WORD':
                                                        value_text += child_block['Text'] + ' '
                                                        value_confidence = child_block.get('Confidence', 0)

                        field_name = key_text.strip().lower()
                        if field_name:
                            extracted_fields[field_name] = value_text.strip()
                            confidence_scores[field_name] = {
                                'key_confidence': key_confidence,
                                'value_confidence': value_confidence,
                                'overall_confidence': (key_confidence + value_confidence) / 2
                            }

            validation_results = {}
            missing_fields = []

            for required_field in required_fields:
                normalized_field = required_field.lower()
                if normalized_field in extracted_fields:
                    confidence = confidence_scores[normalized_field]['overall_confidence']
                    is_valid = confidence >= 80.0
                    validation_results[required_field] = {
                        'value': extracted_fields[normalized_field],
                        'confidence': confidence,
                        'valid': is_valid
                    }
                else:
                    missing_fields.append(required_field)
                    validation_results[required_field] = {
                        'value': None,
                        'confidence': 0.0,
                        'valid': False
                    }

            return {
                'extracted_fields': extracted_fields,
                'confidence_scores': confidence_scores,
                'validation_results': validation_results,
                'missing_fields': missing_fields,
                'all_required_present': len(missing_fields) == 0
            }

        except ClientError as e:
            return {
                'error': str(e),
                'extracted_fields': {},
                'confidence_scores': {},
                'validation_results': {},
                'missing_fields': required_fields,
                'all_required_present': False
            }
